from oauth2_provider.models import Application
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from django.shortcuts import get_object_or_404

@api_view(['PATCH'])
@permission_classes([IsAuthenticated])
def update_oauth_redirect_uris(request, app_id):
    app = get_object_or_404(Application, id=app_id, user=request.user)
    new_redirect_uris = request.data.get('redirect_uris')
    if not new_redirect_uris:
        return Response({'error': 'redirect_uris required'}, status=status.HTTP_400_BAD_REQUEST)
    app.redirect_uris = new_redirect_uris
    app.save(update_fields=['redirect_uris'])
    return Response({'id': app.id, 'name': app.name, 'redirect_uris': app.redirect_uris})
